L(check_key):
        cmeq    v0.4s, v12.4s, v26.4s
        cmeq    v1.4s, v14.4s, v26.4s
        cmeq    v2.4s, v15.4s, v26.4s
        cmeq    v3.4s, v17.4s, v26.4s
        orr     v4.16b, v0.16b, v1.16b
        orr     v5.16b, v2.16b, v3.16b
        orr     v4.16b, v4.16b, v5.16b
        umaxv   s4, v4.4s
        fmov    w16, s4
        cbnz    w16, L(check_hi)

L(next_key):
        subs    w9, w9, #1
        b.eq    L(finished_nothing)
        add     w13, w13, #16
        tbnz    w13, #8, L(carry_hi)
        str     w13, [x0, #16]
L(swap_tables):
        mov     x16, x12                   // other (just prepped) -> current
        sub     x12, x10, #832            // current -> other
        mov     x11, x16
        add     x10, x16, #832
        b       L(batch_loop)

L(carry_hi):
        // the prep that ran alongside this batch assumed no carry out of L0hi:
        // discard it, step mid/lo, recompute the pre_* values, re-prep the other
        // table, and continue
        and     w13, w13, #0xFF
        str     w13, [x0, #16]
        rev     w14, w14
        adds    w14, w14, #1
        rev     w14, w14
        b.cc    L(redo_mid)
        rev     w15, w15
        add     w15, w15, #1
        rev     w15, w15
        // recompute pre_B_0/pre_S1 (lo changed), then fall through
        mov     w16, #0x8B1D
        movk    w16, #0xBF0A, lsl #16
        add     w2, w15, w16
        ror     w2, w2, #3
        str     w2, [sp, #160]
        mov     w16, #0x5639
        movk    w16, #0x1523, lsl #16
        add     w3, w2, w16
        ror     w3, w3, #29
        str     w3, [sp, #164]
L(redo_mid):
        ldr     w2, [sp, #160]
        ldr     w3, [sp, #164]
        add     w16, w2, w3
        add     w17, w14, w16
        neg     w2, w16
        ror     w17, w17, w2
        str     w17, [sp, #168]
        mov     w2, #0x44D5
        movk    w2, #0xF450, lsl #16
        add     w2, w2, w3
        add     w2, w2, w17
        ror     w2, w2, #29
        str     w2, [sp, #172]
        add     w16, w17, w2
        str     w16, [sp, #176]
        str     w13, [sp, #180]
        bl      L(scalar_prep)              // into [x12], the stale table
        b       L(swap_tables)

L(check_hi):
        // Rare path (about 1 batch in 2^28); scalar-pool registers (w2-w4) are
        // dead here, and x10/x12 (the table pointers) must stay intact.
        adr     x16, L(weights)
        ldr     q4, [x16]
        and     v5.16b, v0.16b, v4.16b
        addv    s5, v5.4s
        fmov    w2, s5
        and     v5.16b, v1.16b, v4.16b
        addv    s5, v5.4s
        fmov    w3, s5
        orr     w2, w2, w3, lsl #4
        and     v5.16b, v2.16b, v4.16b
        addv    s5, v5.4s
        fmov    w3, s5
        orr     w2, w2, w3, lsl #8
        and     v5.16b, v3.16b, v4.16b
        addv    s5, v5.4s
        fmov    w3, s5
        orr     w2, w2, w3, lsl #12
        // w2 = 16-bit low-word match mask, bit n = key n

        // k=77: S[25] = (S[25] + A + B_1) <<< 3, then D = ((D ^ C) <<< C) + S[25]
        ldp     q4, q5, [x10, #768]
        ldp     q6, q7, [x10, #800]
        add     v8.4s, v8.4s, v4.4s
        add     v9.4s, v9.4s, v5.4s
        add     v10.4s, v10.4s, v6.4s
        add     v11.4s, v11.4s, v7.4s
        add     v8.4s, v8.4s, v13.4s
        add     v9.4s, v9.4s, v16.4s
        add     v10.4s, v10.4s, v19.4s
        add     v11.4s, v11.4s, v22.4s
        shl     v0.4s, v8.4s, #3
        shl     v1.4s, v9.4s, #3
        shl     v2.4s, v10.4s, #3
        shl     v3.4s, v11.4s, #3
        sri     v0.4s, v8.4s, #29
        sri     v1.4s, v9.4s, #29
        sri     v2.4s, v10.4s, #29
        sri     v3.4s, v11.4s, #29
        eor     v18.16b, v18.16b, v12.16b
        eor     v20.16b, v20.16b, v14.16b
        eor     v21.16b, v21.16b, v15.16b
        eor     v23.16b, v23.16b, v17.16b
        and     v4.16b, v12.16b, v24.16b
        and     v5.16b, v14.16b, v24.16b
        and     v6.16b, v15.16b, v24.16b
        and     v7.16b, v17.16b, v24.16b
        orr     v8.16b, v12.16b, v25.16b
        orr     v9.16b, v14.16b, v25.16b
        orr     v10.16b, v15.16b, v25.16b
        orr     v11.16b, v17.16b, v25.16b
        ushl    v4.4s, v18.4s, v4.4s
        ushl    v5.4s, v20.4s, v5.4s
        ushl    v6.4s, v21.4s, v6.4s
        ushl    v7.4s, v23.4s, v7.4s
        ushl    v8.4s, v18.4s, v8.4s
        ushl    v9.4s, v20.4s, v9.4s
        ushl    v10.4s, v21.4s, v10.4s
        ushl    v11.4s, v23.4s, v11.4s
        orr     v18.16b, v4.16b, v8.16b
        orr     v20.16b, v5.16b, v9.16b
        orr     v21.16b, v6.16b, v10.16b
        orr     v23.16b, v7.16b, v11.16b
        add     v18.4s, v18.4s, v0.4s
        add     v20.4s, v20.4s, v1.4s
        add     v21.4s, v21.4s, v2.4s
        add     v23.4s, v23.4s, v3.4s
        cmeq    v0.4s, v18.4s, v27.4s
        cmeq    v1.4s, v20.4s, v27.4s
        cmeq    v2.4s, v21.4s, v27.4s
        cmeq    v3.4s, v23.4s, v27.4s
        adr     x16, L(weights)
        ldr     q4, [x16]
        and     v5.16b, v0.16b, v4.16b
        addv    s5, v5.4s
        fmov    w3, s5
        and     v5.16b, v1.16b, v4.16b
        addv    s5, v5.4s
        fmov    w16, s5
        orr     w3, w3, w16, lsl #4
        and     v5.16b, v2.16b, v4.16b
        addv    s5, v5.4s
        fmov    w16, s5
        orr     w3, w3, w16, lsl #8
        and     v5.16b, v3.16b, v4.16b
        addv    s5, v5.4s
        fmov    w16, s5
        orr     w3, w3, w16, lsl #12
        ands    w16, w3, w2                // keys matching both words
        b.ne    L(save_found_key)

        // partial match(es) only: count them, record the last one
        fmov    s4, w2
        cnt     v4.8b, v4.8b
        addv    b4, v4.8b
        fmov    w4, s4
        ldr     w16, [x0, #28]
        add     w16, w16, w4
        str     w16, [x0, #28]
        clz     w16, w2
        mov     w4, #31
        sub     w16, w4, w16
        add     w16, w16, w13
        str     w16, [x0, #32]
        str     w14, [x0, #36]
        str     w15, [x0, #40]
        b       L(next_key)

L(save_found_key):
        rbit    w16, w16
        clz     w3, w16                    // w3 = first full match
        mov     w4, #2
        lsl     w4, w4, w3
        sub     w4, w4, #1
        and     w2, w2, w4
        fmov    s4, w2
        cnt     v4.8b, v4.8b
        addv    b4, v4.8b
        fmov    w4, s4
        ldr     w16, [x0, #28]
        add     w16, w16, w4
        str     w16, [x0, #28]
        add     w16, w3, w13
        str     w16, [x0, #32]
        str     w14, [x0, #36]
        str     w15, [x0, #40]
        // *iterations = keys before the winning one
        ldr     x8, [sp, #144]
        ldr     w16, [x8]
        lsr     w16, w16, #4
        sub     w16, w16, w9
        lsl     w16, w16, #4
        add     w16, w16, w3
        str     w16, [x8]
        str     w14, [x0, #20]
        str     w15, [x0, #24]
        mov     w0, #2                     // RESULT_FOUND
        b       L(finished)

L(finished_nothing):
        add     w13, w13, #16
        ubfx    w16, w13, #8, #1
        and     w13, w13, #0xFF
        rev     w14, w14
        rev     w15, w15
        adds    w14, w14, w16
        adc     w15, w15, wzr
        rev     w14, w14
        rev     w15, w15
        str     w13, [x0, #16]
        str     w14, [x0, #20]
        str     w15, [x0, #24]
        mov     w0, #1                     // RESULT_NOTHING

L(finished):
        ldp     d8, d9, [sp, #0]
        ldp     d10, d11, [sp, #16]
        ldp     d12, d13, [sp, #32]
        ldp     d14, d15, [sp, #48]
        ldp     x19, x20, [sp, #64]
        ldp     x21, x22, [sp, #80]
        ldp     x23, x24, [sp, #96]
        ldp     x25, x26, [sp, #112]
        ldp     x27, x28, [sp, #128]
        mov     sp, x29
        ldp     x29, x30, [sp], #16
        ret

        // standalone scalar prep: the pipeline prologue, and the redo after an
        // L0hi byte carry. In: x12 = target table base, [sp, SP_HI] = prep L0hi.
L(scalar_prep):
        str     x30, [sp, #184]
        // ---- scalar subgroup 0: keys 0..3 of the next batch
        ldr     w11, [sp, #172]
        mov     w2, w11
        mov     w3, w11
        mov     w4, w11
        mov     w5, w11
        ldr     w11, [sp, #160]
